-- Medium-Easy economy policy. The starter pack remains useful without granting
-- finished +12 / -7 / fully socketed end-game equipment on day one.
local function Imperial_NormalizeStarterItem(tItem)
    tItem.Plus = math.min(tonumber(tItem.Plus) or 0, 3)
    tItem.Bless = math.min(tonumber(tItem.Bless) or 0, 3)
    tItem.Enchant = math.min(tonumber(tItem.Enchant) or 0, 100)
    if (tonumber(tItem.Sock1) or 0) ~= 0 then tItem.Sock1 = 255 end
    tItem.Sock2 = 0
end

for _, tItem in ipairs(tImperial_SharedPack or {}) do
    Imperial_NormalizeStarterItem(tItem)
end
for _, tClassPack in pairs(tImperial_ClassPacks or {}) do
    for _, tItem in ipairs(tClassPack) do
        Imperial_NormalizeStarterItem(tItem)
    end
end
